{
  "query": "mutation StoreSchema($key: String!, $schema: JSON!) { storeSchema(key: $key, schema: $schema) { __typename ... on StoreSchemaResult { schema { key version } } ... on BadRequestError { code message } } }",
  "variables": {
    "key": "wallet-v1",
    "schema": { "accounts": [], "entryTypes": [] }
  }
}

{
  "query": "mutation CreateLedger($ik: SafeString!, $name: String!, $schemaKey: String!) { createLedger(ik: $ik, name: $name, schemaKey: $schemaKey) { __typename ... on CreateLedgerResult { ledger { ik name type } } ... on BadRequestError { code message } } }",
  "variables": {
    "ik": "main",
    "name": "Main Ledger",
    "schemaKey": "wallet-v1"
  }
}

{
  "query": "query GetLedger($ik: SafeString!) { ledger(ik: $ik) { ik name type created ledgerAccounts { path type } } }",
  "variables": { "ik": "main" }
}

{
  "query": "mutation PostEntry($ik: SafeString!) { addLedgerEntry(ledgerIk: \"main\", ik: $ik, type: \"deposit\", date: \"2026-07-01\", parameters: {amount: \"10.00\", currency: {code: \"USD\"}, userId: \"user-123\"}) { __typename ... on AddLedgerEntryResult { entry { ik posted lines { amount currency { code } type account { path } } } } ... on BadRequestError { code message } } }",
  "variables": { "ik": "deposit-0001" }
}

{
  "query": "mutation Reverse($ik: SafeString!) { reverseLedgerEntry(ledgerIk: \"main\", ik: $ik, entryIk: \"deposit-0001\") { __typename ... on ReverseLedgerEntryResult { entry { ik isReversal } } ... on BadRequestError { code message } } }",
  "variables": { "ik": "reverse-0001" }
}

{
  "query": "query Lines { getLedgerAccountLines(ledgerIk: \"main\", path: \"user_funds/user-123\", first: 20) { nodes { amount currency { code } type posted } pageInfo { hasNextPage endCursor } } }"
}

{
  "query": "mutation Reconcile { reconcileTx(ledgerIk: \"main\", txId: \"psp-tx-987\", parameters: {amount: \"10.00\", currency: {code: \"USD\"}}) { __typename ... on ReconcileTxResult { reconciled } ... on BadRequestError { code message } } }"
}
